From fe786f73c502597a1f7e81827e9aad205f0de3c3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:07:39 +0100
Subject: [PATCH] kded: offer the VPN's log when a VPN connection fails to
 activate

NetworkManager doesn't say why a VPN plugin failed, so the notification
only said that the connection failed. It now has a Show Log button that
shows what NetworkManager and the VPN plugin logged during the attempt.

BUG: 496888
---
 kded/notification.cpp | 73 ++++++++++++++++++++++++++++++++++++++++++-
 kded/notification.h   |  1 +
 2 files changed, 73 insertions(+), 1 deletion(-)

diff --git a/kded/notification.cpp b/kded/notification.cpp
index 217998364..1c93446d8 100644
--- a/kded/notification.cpp
+++ b/kded/notification.cpp
@@ -17,16 +17,48 @@

 #include <KLocalizedString>
 #include <KNotification>
+#include <KWindowSystem>

 #include <QDBusConnection>
+#include <QDateTime>
+#include <QDialog>
+#include <QDialogButtonBox>
+#include <QFontDatabase>
 #include <QIcon>
+#include <QPlainTextEdit>
+#include <QProcess>
+#include <QStandardPaths>
 #include <QTimer>
+#include <QVBoxLayout>

 #include <algorithm>
 #include <chrono>

 using namespace std::chrono_literals;

+static void showVpnLog(const QString &vpnName, const QString &log)
+{
+    auto dialog = new QDialog;
+    dialog->setAttribute(Qt::WA_DeleteOnClose);
+    dialog->setWindowTitle(i18nc("@title:window", "VPN Connection Log – %1", vpnName));
+    dialog->setWindowIcon(QIcon::fromTheme(QStringLiteral("network-vpn")));
+
+    auto logView = new QPlainTextEdit(log, dialog);
+    logView->setReadOnly(true);
+    logView->setLineWrapMode(QPlainTextEdit::NoWrap);
+    logView->setFont(QFontDatabase::systemFont(QFontDatabase::FixedFont));
+
+    auto buttonBox = new QDialogButtonBox(QDialogButtonBox::Close, dialog);
+    QObject::connect(buttonBox, &QDialogButtonBox::rejected, dialog, &QDialog::reject);
+
+    auto layout = new QVBoxLayout(dialog);
+    layout->addWidget(logView);
+    layout->addWidget(buttonBox);
+
+    dialog->resize(900, 500);
+    dialog->show();
+}
+
 Notification::Notification(QObject *parent)
     : QObject(parent)
 {
@@ -306,6 +338,7 @@ void Notification::addActiveConnection(const NetworkManager::ActiveConnection::P
     if (ac->vpn()) {
         NetworkManager::VpnConnection::Ptr vpnConnection = ac.objectCast<NetworkManager::VpnConnection>();
         connect(vpnConnection.data(), &NetworkManager::VpnConnection::stateChanged, this, &Notification::onVpnConnectionStateChanged);
+        m_vpnActivationTimes.insert(ac->path(), QDateTime::currentSecsSinceEpoch());
     } else if (ac->type() != NetworkManager::ConnectionSettings::Bond //
                && ac->type() != NetworkManager::ConnectionSettings::Bridge //
                && ac->type() != NetworkManager::ConnectionSettings::Generic //
@@ -430,6 +463,11 @@ void Notification::onVpnConnectionStateChanged(NetworkManager::VpnConnection::St
     QString eventId, text;
     const QString vpnName = vpn->connection()->name();
     const QString connectionId = vpn->path();
+    const qint64 activationTime = m_vpnActivationTimes.value(connectionId);
+
+    if (state == NetworkManager::VpnConnection::Failed || state == NetworkManager::VpnConnection::Disconnected) {
+        m_vpnActivationTimes.remove(connectionId);
+    }

     if (state == NetworkManager::VpnConnection::Activated) {
         eventId = QStringLiteral("ConnectionActivated");
@@ -503,7 +541,40 @@ void Notification::onVpnConnectionStateChanged(NetworkManager::VpnConnection::St
     notify->setTitle(vpnName);
     notify->setText(text.toHtmlEscaped());
     m_notifications[connectionId] = notify;
-    notify->sendEvent();
+
+    const QString journalctl = QStandardPaths::findExecutable(QStringLiteral("journalctl"));
+    if (state != NetworkManager::VpnConnection::Failed || !activationTime || journalctl.isEmpty()) {
+        notify->sendEvent();
+        return;
+    }
+
+    // NetworkManager doesn't tell why a VPN plugin failed, but NetworkManager and the plugin log it,
+    // so offer what they logged during this activation attempt
+    auto journal = new QProcess(this);
+    connect(journal, &QProcess::finished, this, [journal, notify, vpnName]() {
+        journal->deleteLater();
+        const QString log = QString::fromUtf8(journal->readAllStandardOutput()).trimmed();
+        if (!log.isEmpty()) {
+            auto showLogAction = notify->addAction(i18n("Show Log"));
+            connect(showLogAction, &KNotificationAction::activated, notify, [notify, vpnName, log]() {
+                KWindowSystem::setCurrentXdgActivationToken(notify->xdgActivationToken());
+                showVpnLog(vpnName, log);
+            });
+        }
+        notify->sendEvent();
+    });
+    connect(journal, &QProcess::errorOccurred, this, [journal, notify](QProcess::ProcessError error) {
+        if (error == QProcess::FailedToStart) {
+            journal->deleteLater();
+            notify->sendEvent();
+        }
+    });
+    journal->start(journalctl,
+                   {QStringLiteral("--unit=NetworkManager.service"),
+                    QStringLiteral("--since=@%1").arg(activationTime),
+                    QStringLiteral("--output=short"),
+                    QStringLiteral("--no-pager"),
+                    QStringLiteral("--quiet")});
 }

 void Notification::notificationClosed()
diff --git a/kded/notification.h b/kded/notification.h
index f9afb1268..ee174e8d0 100644
--- a/kded/notification.h
+++ b/kded/notification.h
@@ -44,6 +44,7 @@ private Q_SLOTS:

 private:
     QHash<QString, KNotification *> m_notifications;
+    QHash<QString, qint64> m_vpnActivationTimes;

     bool m_preparingForSleep = false;
     bool m_justLaunched = true;
